import{_ as e,o as a,c as i,a2 as s}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"Evaluation Methodology","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/evaluation-methodology.md","filePath":"concepts/evaluation-methodology.md","lastUpdated":null}'),r={name:"concepts/evaluation-methodology.md"};function o(n,t,l,d,c,h){return a(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="evaluation-methodology" tabindex="-1">Evaluation Methodology <a class="header-anchor" href="#evaluation-methodology" aria-label="Permalink to &quot;Evaluation Methodology&quot;">​</a></h1><p>Following defence test &amp; evaluation practice.</p><h2 id="the-kpp-gate" tabindex="-1">The KPP Gate <a class="header-anchor" href="#the-kpp-gate" aria-label="Permalink to &quot;The KPP Gate&quot;">​</a></h2><p>Every scheduler is first judged against <strong>hard Key Performance Parameters</strong>. Failing any gate means the system is <strong>not mission-capable</strong>, regardless of how well it scores on other metrics.</p><table tabindex="0"><thead><tr><th>KPP</th><th>Threshold</th><th>Rationale</th></tr></thead><tbody><tr><td>Threat coverage (Pd)</td><td>≥ 0.90</td><td>PS primary objective: high interception rate</td></tr><tr><td>Prediction accuracy</td><td>≥ 0.50</td><td>PS FoM: predictions better than chance</td></tr><tr><td>False alarm rate</td><td>≤ 5×10⁻⁴ /slot</td><td>Operator loading limit</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The gate is <strong>all-or-nothing</strong>. A scheduler with 99% prediction accuracy but 89% threat coverage fails. A scheduler with 100% coverage but 49% prediction accuracy fails.</p></div><h2 id="mission-effectiveness-score-mes" tabindex="-1">Mission Effectiveness Score (MES) <a class="header-anchor" href="#mission-effectiveness-score-mes" aria-label="Permalink to &quot;Mission Effectiveness Score (MES)&quot;">​</a></h2><p>Among KPP-passing systems, the MES ranks schedulers by a composite of six normalised figures of merit:</p><ol><li><strong>Pd (threat coverage)</strong> — fraction of hostile emitters caught at least once</li><li><strong>1 - Pfa (relative false-alarm performance)</strong> — fewer false alarms is better</li><li><strong>Average intercept rate</strong> — fraction of dwells that produce detections</li><li><strong>Reward (relative)</strong> — normalised to the field leader</li><li><strong>Prediction accuracy</strong> — fraction of correct ON/OFF predictions</li><li><strong>Intercept-time error (relative)</strong> — how accurately the scheduler predicts when emitters will transmit</li></ol><p>MES = mean of all six normalised components.</p><h2 id="headline-result" tabindex="-1">Headline result <a class="header-anchor" href="#headline-result" aria-label="Permalink to &quot;Headline result&quot;">​</a></h2><p><strong>SmartScan is the only mission-capable scheduler in the field.</strong></p><table tabindex="0"><thead><tr><th>Scheduler</th><th>Coverage</th><th>Prediction</th><th>Verdict</th><th>MES</th></tr></thead><tbody><tr><td>SmartScan</td><td>95.0% ✅</td><td>62.3% ✅</td><td><strong>CAPABLE</strong></td><td><strong>0.628</strong></td></tr><tr><td>UCB bandit</td><td>54.0% ❌</td><td>98.8% ✅</td><td>NOT CAPABLE</td><td>0.680</td></tr><tr><td>Random scan</td><td>97.7% ✅</td><td>45.8% ❌</td><td>NOT CAPABLE</td><td>0.437</td></tr><tr><td>Q-learning</td><td>89.6% ❌</td><td>19.0% ❌</td><td>NOT CAPABLE</td><td>0.230</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>UCB bandit has a higher raw MES but fails the KPP gate because it misses 46% of threats. The gate ensures operational viability before ranking.</p></div><h2 id="statistical-significance" tabindex="-1">Statistical significance <a class="header-anchor" href="#statistical-significance" aria-label="Permalink to &quot;Statistical significance&quot;">​</a></h2><p>Paired per-episode permutation tests on the gated MES score, with Holm-Bonferroni correction at α=0.05:</p><ul><li>SmartScan vs UCB bandit: <strong>p &lt; 1e-4</strong> ✓</li><li>SmartScan vs Random scan: <strong>p &lt; 1e-4</strong> ✓</li><li>SmartScan vs Q-learning: <strong>p &lt; 1e-4</strong> ✓</li></ul><p>200 held-out episodes with 95% confidence intervals.</p><h2 id="regenerating-results" tabindex="-1">Regenerating results <a class="header-anchor" href="#regenerating-results" aria-label="Permalink to &quot;Regenerating results&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ewsmart.experiments</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> full</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This runs the complete evaluation suite (~10 minutes):</p><ul><li>Monte Carlo evaluation (200 episodes per scheduler)</li><li>Statistical significance tests</li><li>Mission Effectiveness Score with KPP gating</li><li>Sensitivity analysis (bands, SNR, agility, density)</li><li>Ablation study</li><li>Multi-receiver cooperative evaluation</li><li>ROC analysis</li><li>Geolocation accuracy study</li></ul>',22)])])}const u=e(r,[["render",o]]);export{g as __pageData,u as default};
